CREATE POLICY "community_media_read" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'community-media');
CREATE POLICY "community_media_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'community-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "community_media_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'community-media' AND (storage.foldername(name))[1] = auth.uid()::text);